{
  "interpretation": {
    "name": "TightenLine3F35WithSharedNutrunner",
    "scope": {"line": 3, "station": "st3", "tool": "NR7", "variant": "F35"},
    "goal": "Bring the shared nutrunner NR7 to station st3, tighten the fasteners of variant F35 according to its MES program, evaluate and record the result, then return the tool to the crib.",
    "constraints": [
      "NR7 must be reserved before use and released after it is back in the crib",
      "NR7 must be at st3 before configure-tool and tighten-fasteners",
      "The tightening program must be obtained via get-program and contain no literal values",
      "The tightening must be evaluated and recorded",
      "transport-tool must be delegated to agvexecutor",
      "NR7 must be returned to the crib when the work is done"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "single execution, now",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line3-f35-tightening-with-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "tighten",
        "next": "quality",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["tighten-bolts"], "dep": ["program", "reserve", "transport-to-station"], "executor": null, "params": {}},
          {"name": "tighten-bolts", "service": "tighten-fasteners", "next": [], "dep": ["configure", "reserve"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "quality",
        "next": "return-tool",
        "steps": [
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["tighten-bolts", "program"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten-bolts"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "return-tool",
        "next": null,
        "steps": [
          {"name": "transport-to-crib", "service": "transport-tool", "next": ["release"], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release", "service": "release-tool", "next": [], "dep": ["reserve"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
